import { DomainError } from "./errors";

export type OrderState = "placed" | "paid" | "packed" | "shipped" | "delivered" | "cancelled";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

const NEXT_STATE: Readonly<Record<Exclude<OrderState, "delivered" | "cancelled">, OrderState>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
};

export class Order {
  private currentState: OrderState = "placed";

  public constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
  ) {
    if (!id || !customerId || lines.length === 0) {
      throw new DomainError("An order requires an id, customer, and at least one line");
    }
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public advanceTo(nextState: Exclude<OrderState, "placed" | "cancelled">): void {
    if (this.currentState === "delivered" || this.currentState === "cancelled") {
      throw new DomainError(`Cannot transition an order in state ${this.currentState}`);
    }
    if (NEXT_STATE[this.currentState] !== nextState) {
      throw new DomainError(`Order must move from ${this.currentState} to ${NEXT_STATE[this.currentState]}`);
    }
    this.currentState = nextState;
  }

  public cancel(): void {
    if (this.currentState === "shipped" || this.currentState === "delivered") {
      throw new DomainError("A shipped order cannot be cancelled");
    }
    if (this.currentState === "cancelled") {
      throw new DomainError("Order is already cancelled");
    }
    this.currentState = "cancelled";
  }
}

