import { DomainError, InsufficientStockError } from "./errors";

export class Product {
  public constructor(
    public readonly id: string,
    public readonly name: string,
    private availableQuantity: number,
  ) {
    if (!id || !name || !Number.isInteger(availableQuantity) || availableQuantity < 0) {
      throw new DomainError("A product requires an id, name, and non-negative integer stock");
    }
  }

  public get stock(): number {
    return this.availableQuantity;
  }

  public canReserve(quantity: number): boolean {
    this.assertPositiveQuantity(quantity);
    return this.availableQuantity >= quantity;
  }

  public reserve(quantity: number): void {
    this.assertPositiveQuantity(quantity);
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id);
    }
    this.availableQuantity -= quantity;
  }

  public release(quantity: number): void {
    this.assertPositiveQuantity(quantity);
    this.availableQuantity += quantity;
  }

  private assertPositiveQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new DomainError("Quantity must be a positive integer");
    }
  }
}

